import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    a = list(map(int, data[1:1+n]))

    # dp[i] = length of longest valid contest ending at a[i]
    dp = [1] * n

    for i in range(n):
        for j in range(i):
            if a[j] * 2 >= a[i]:
                dp[i] = max(dp[i], dp[j] + 1)

    print(max(dp))

if __name__ == "__main__":
    solve()
"}

