import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    k = int(data[1])

    grid = []
    idx = 2
    for i in range(n):
        row = data[idx:idx+n]
        grid.append(row)
        idx += n

    # Initial white lines
    white_rows = [False] * n
    white_cols = [False] * n

    for i in range(n):
        all_white = True
        for j in range(n):
            if grid[i][j] == 'B':
                all_white = False
                break
        white_rows[i] = all_white

    for j in range(n):
        all_white = True
        for i in range(n):
            if grid[i][j] == 'B':
                all_white = False
                break
        white_cols[j] = all_white

    max_white_lines = 0

    # Try all possible click positions
    for click_row in range(n - k + 1):
        for click_col in range(n - k + 1):
            # Simulate eraser effect
            new_white_rows = white_rows[:]
            new_white_cols = white_cols[:]

            # Check affected rows
            for row in range(click_row, click_row + k):
                all_white = True
                for col in range(n):
                    # If cell is black and not in eraser area, it's still black
                    if grid[row][col] == 'B' and not (click_row <= row < click_row + k and click_col <= col < click_col + k):
                        all_white = False
                        break
                if all_white:
                    new_white_rows[row] = True

            # Check affected columns
            for col in range(click_col, click_col + k):
                all_white = True
                for row in range(n):
                    # If cell is black and not in eraser area, it's still black
                    if grid[row][col] == 'B' and not (click_row <= row < click_row + k and click_col <= col < click_col + k):
                        all_white = False
                        break
                if all_white:
                    new_white_cols[col] = True

            # Count white lines
            count = sum(new_white_rows) + sum(new_white_cols)
            max_white_lines = max(max_white_lines, count)

    print(max_white_lines)

if __name__ == "__main__":
    solve()
"}

