def solve():
    t = int(input())
    for _ in range(t):
        n = int(input())
        grid = []
        for _ in range(n):
            grid.append(list(input().strip()))

        # Count total tokens
        k = sum(row.count('X') + row.count('O') for row in grid)
        max_ops = k // 3

        # Function to check if there's a winning configuration
        def has_win():
            # Check rows
            for i in range(n):
                for j in range(n - 2):
                    if grid[i][j] == grid[i][j+1] == grid[i][j+2] != '.':
                        return True, i, j, j+1, j+2, grid[i][j]

            # Check columns
            for j in range(n):
                for i in range(n - 2):
                    if grid[i][j] == grid[i+1][j] == grid[i+2][j] != '.':
                        return True, i, j, i+1, i+2, grid[i][j]

            return False, -1, -1, -1, -1, -1

        # Function to apply operation
        def apply_op(i1, j1, i2, j2, i3, j3, new_val):
            # Change the middle token
            mid_i = (i1 + i2 + i3) // 3
            mid_j = (j1 + j2 + j3) // 3
            grid[mid_i][mid_j] = new_val

        # Break winning configurations
        ops = 0
        while ops < max_ops:
            has_win_flag, i1, j1, i2, j2, token = has_win()
            if not has_win_flag:
                break

            # Apply operation
            apply_op(i1, j1, i2, j2, i3, j3, 'X' if token == 'O' else 'O')
            ops += 1

        # Print result
        for row in grid:
            print(''.join(row))

solve()
