import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    numbers = list(map(int, data[1:1+n]))

    # Count occurrences of each number
    count = {}
    for num in numbers:
        count[num] = count.get(num, 0) + 1

    # Find numbers that appear exactly once (potential endpoints)
    endpoints = [num for num, cnt in count.items() if cnt == 1]

    # If we have exactly two endpoints, check if they differ by 1
    if len(endpoints) == 2:
        a, b = endpoints
        if abs(a - b) == 1:
            print("YES")
        else:
            print("NO")
    else:
        print("NO")

if __name__ == "__main__":
    solve()
