import sys

def is_draw(grid, n):
    """Check if the grid is a draw configuration"""
    for i in range(n):
        # Check rows
        for j in range(n - 2):
            if grid[i][j] == grid[i][j+1] == grid[i][j+2] != '.':
                return False
        # Check columns
        for j in range(n - 2):
            if grid[j][i] == grid[j+1][i] == grid[j+2][i] != '.':
                return False
    return True

def solve_test_case(n, grid):
    """Solve a single test case"""
    # Check if already a draw
    if is_draw(grid, n):
        return grid

    # Create a copy to modify
    result = [row[:] for row in grid]

    # Find and fix winning configurations
    while True:
        # Check rows
        for i in range(n):
            for j in range(n - 2):
                if grid[i][j] == grid[i][j+1] == grid[i][j+2] != '.':
                    # Winning configuration in row i, columns j, j+1, j+2
                    # Change the middle one
                    result[i][j+1] = 'O' if grid[i][j+1] == 'X' else 'X'
                    # Update grid to reflect changes for subsequent checks
                    grid[i][j+1] = result[i][j+1]
                    return result

        # Check columns
        for i in range(n):
            for j in range(n - 2):
                if grid[j][i] == grid[j+1][i] == grid[j+2][i] != '.':
                    # Winning configuration in column i, rows j, j+1, j+2
                    # Change the middle one
                    result[j+1][i] = 'O' if grid[j+1][i] == 'X' else 'X'
                    # Update grid to reflect changes for subsequent checks
                    grid[j+1][i] = result[j+1][i]
                    return result

        # If no winning configurations found, we're done
        return result

