def solve():
    import sys
    input = sys.stdin.read().split()

    idx = 0
    t = int(input[idx])
    idx += 1

    results = []

    for _ in range(t):
        # Skip empty line
        while idx < len(input) and input[idx] == '':
            idx += 1

        if idx >= len(input):
            break

        n = int(input[idx])
        m = int(input[idx+1])
        idx += 2

        # Read edges
        graph = defaultdict(list)
        for _ in range(m):
            a = int(input[idx])
            b = int(input[idx+1])
            graph[a].append(b)
            idx += 2

        # Find all vertices reachable from 1
        reachable = set()
        visited = set()
        queue = deque([1])
        visited.add(1)

        while queue:
            u = queue.popleft()
            reachable.add(u)
            for v in graph[u]:
                if v not in visited:
                    visited.add(v)
                    queue.append(v)

        # Check for cycles in reachable subgraph
        has_cycle = False
        visited = set()
        queue = deque([1])
        visited.add(1)
        parent = {}

        while queue:
            u = queue.popleft()
            for v in graph[u]:
                if v not in visited:
                    visited.add(v)
                    parent[v] = u
                    queue.append(v)
                elif v in parent and parent[v] != u:
                    # Found a cycle
                    has_cycle = True
                    break
            if has_cycle:
                break

        if has_cycle:
            # All vertices in reachable subgraph have infinite paths
            results.extend([-1] * n)
        else:
            # Count paths using topological sort
            dp = [0] * (n + 1)
            dp[1] = 1  # Empty path

            # Topological sort
            in_degree = [0] * (n + 1)
            for u in reachable:
                for v in graph[u]:
                    in_degree[v] += 1

            queue = deque()
            for v in reachable:
                if in_degree[v] == 0:
                    queue.append(v)

            while queue:
                u = queue.popleft()
                for v in graph[u]:
                    dp[v] += dp[u]
                    in_degree[v] -= 1
                    if in_degree[v] == 0:
                        queue.append(v)

            for v in range(1, n + 1):
                if v in reachable:
                    if dp[v] == 1:
                        results.append(1)
                    elif dp[v] > 1:
                        results.append(2)
                    else:
                        results.append(0)
                else:
