import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    arr = list(map(int, data[1:1+n]))

    # Sort the array to find the i-th smallest values
    arr_sorted = sorted(arr)

    # For each position, find the minimum possible value
    result = []
    for i in range(n):
        # Position 0: we can always get 1 by replacing any element with 1
        if i == 0:
            result.append(1)
        else:
            # For position i > 0:
            # - If there is at least one 1 in the array, we can get 1 at position 1
            #   by replacing another element with 1
            # - Otherwise, we get the i-th smallest value from the original array
            if 1 in arr_sorted[:i]:
                result.append(1)
            else:
                result.append(arr_sorted[i])

    print(' '.join(map(str, result)))

if __name__ == '__main__':
    solve()
