def solve():
    N = int(input())
    board = []
    pos = {}
    for i in range(N):
        row = list(map(int, input().split()))
        for j in range(N):
            num = row[j]
            pos[num] = (i, j)

    # Positions for numbers 1 to N^2
    targets = [pos[k] for k in range(1, N*N + 1)]

    # Movement rules
    def knight_moves(pos):
        i, j = pos
        moves = []
        for di, dj in [(-2, -1), (-2, 1), (-1, -2), (-1, 2), (1, -2), (1, 2), (2, -1), (2, 1)]:
            ni, nj = i + di, j + dj
            if 0 <= ni < N and 0 <= nj < N:
                moves.append((ni, nj))
        return moves

    def bishop_moves(pos):
        i, j = pos
        moves = []
        for di, dj in [(-1, -1), (-1, 1), (1, -1), (1, 1)]:
            ni, nj = i + di, j + dj
            while 0 <= ni < N and 0 <= nj < N:
                moves.append((ni, nj))
                ni += di
                nj += dj
        return moves

    def rook_moves(pos):
        i, j = pos
        moves = []
        for di, dj in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            ni, nj = i + di, j + dj
            while 0 <= ni < N and 0 <= nj < N:
                moves.append((ni, nj))
                ni += di
                nj += dj
        return moves

    # Dijkstra's algorithm
    from heapq import heappush, heappop

    # State: (steps, replacements, position, piece, current_target)
    # piece: 0=knight, 1=bishop, 2=rook

    # Priority queue: (steps, replacements, position, piece, current_target)
    pq = []

    # Start at position 1 with any piece
    for piece in range(3):
        heappush(pq, (0, 0, pos[1], piece, 1))

    # Visited: (position, piece, target)
    visited = set()

    while pq:
        steps, replacements, pos, piece, target = heappop(pq)

        # If we've reached the last target
        if target == N*N:
            return steps, replacements

        # If we've already visited this state
        if (pos, piece, target) in visited:
            continue
        visited.add((pos, piece, target))

