import sys

class SegmentTreeNode:
    def __init__(self, left, right):
        self.left = left
        self.right = right
        self.team_set = set()
        self.team_set.add(left.team)
        self.team_set.add(right.team)
        self.result = '?'
        self.left_child = left
        self.right_child = right

    def update_result(self, result):
        if result == '0':
            self.team_set = {self.left_child.team}
        elif result == '1':
            self.team_set = {self.right_child.team}
        else:
            self.team_set = {self.left_child.team, self.right_child.team}
        self.result = result

    def get_champions(self):
        return len(self.team_set)

def build_tree(teams, start, end):
    if start == end:
        return SegmentTreeNode(teams[start], teams[end])
    mid = (start + end) // 2
    left = build_tree(teams, start, mid)
    right = build_tree(teams, mid + 1, end)
    return SegmentTreeNode(left, right)

