import sys

def solve():
    k = int(sys.stdin.readline())
    s = sys.stdin.readline().strip()
    q = int(sys.stdin.readline())
    queries = []
    for _ in range(q):
        p, c = sys.stdin.readline().split()
        queries.append((int(p) - 1, c))

    n = 2 ** k - 1

    # Binary tree structure: leaves are teams 1..2^k, internal nodes are games
    # We'll use a segment tree approach where each node tracks possible winners
    # For a game at position i, teams are paired: 2i+1 and 2i+2 (0-indexed)
    # Result: 0 means left wins, 1 means right wins, ? means either

    # We'll use a segment tree where each node tracks a set of possible winners
    # Initially, each leaf has a single team
    # For internal nodes, we combine the results of their children

    # Build the segment tree
    class SegmentTree:
        def __init__(self, size):
            self.n = size
            self.tree = [set() for _ in range(2 * self.n)]

        def update(self, pos, value):
            # Update the leaf node
            self.tree[self.n + pos] = {value}

        def combine(self, left, right):
            # Combine results from two children
            if left is None:
                return right
            if right is None:
                return left

            result = set()

            # Process left child results
            for team in left:
                if left is not None and len(left) == 1 and len(right) == 1:
                    # If both children have exactly one team
                    left_team = left.pop()
                    right_team = right.pop()
                    if s[pos] == '0':
                        result.add(left_team)
                    elif s[pos] == '1':
                        result.add(right_team)
                    else:
                        result.add(left_team)
                        result.add(right_team)
                else:
                    # If at least one child has multiple teams
                    if len(left) == 1:
                        left_team = left.pop()
                        # Left child has one team, right has multiple teams
                        # The left team must win
                        for right_team in right:
                            if s[pos] == '0':
                                result.add(left_team)
                            elif s[pos] == '1':
                                # The right team must win, but left_team can't be in result
                                pass
                            else:
                                result.add(left_team)
                    elif len(right) == 1:
                        right_team = right.pop()
                        # Right child has one team, left has multiple teams
                        # The right team must win
                        for left_team in left:
                            if s[pos] == '1':
                                result.add(right_team)
                            elif s[pos] == '0':
                                # The left team must win, but right_team can't be in result
                                pass
                            else:
                                result.add(right_team)
                    else:
                        # Both have multiple teams
                        if s[pos] == '0':
                            # Left child's winner must win
                            for left_team in left:
                                result.add(left_team)
                        elif s[pos] == '1':
                            # Right child's winner must win
                            for right_team in right:
                                result.add(right_team)
                        else:
                            # Either can win
                            for left_team in left:
                                result.add(left_team)
                            for right_team in right:
                                result.add(right_team)

            return result

        def query(self, l, r):
            # Query the range [l, r)
            result = set()
            l += self.n
            r += self.n
            while l < r:
                if l % 2 == 1:
                    result.update(self.combine(result, self.tree[l]))
                    l += 1
                if r % 2 == 1:
                    r -= 1
                    result.update(self.combine(result, self.tree[r]))
                l //= 2
                r //= 2
            return result

    # Initialize segment tree
    st = SegmentTree(n)

    # Set initial values
    for i in range(n):
        if s[i] != '?':
            st.update(i, int(s[i]))

    # Process queries
    for p, c in queries:
        # Update the string
        s = s[:p] + c + s[p+1:]

        # Update the segment tree
        if c != '?':
            st.update(p, int(c))
        else:
            st.update(p, None)

        # Query the root
        result = st.query(0, n)
        print(len(result))

solve()
