import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    it = iter(data)
    n = int(next(it))
    m = int(next(it))

    grid = []
    for _ in range(n):
        row = [int(next(it)) for _ in range(m)]
        grid.append(row)

    # Count white and black cells in rows
    row_white = [0] * n
    row_black = [0] * n
    for i in range(n):
        for j in range(m):
            if grid[i][j] == 0:
                row_white[i] += 1
            else:
                row_black[i] += 1

    # Count white and black cells in columns
    col_white = [0] * m
    col_black = [0] * m
    for j in range(m):
        for i in range(n):
            if grid[i][j] == 0:
                col_white[j] += 1
            else:
                col_black[j] += 1

    # Calculate contributions
    row_contrib = 0
    for i in range(n):
        row_contrib += (1 << row_white[i]) - 1  # white subsets
        row_contrib += (1 << row_black[i]) - 1  # black subsets

    col_contrib = 0
    for j in range(m):
        col_contrib += (1 << col_white[j]) - 1  # white subsets
        col_contrib += (1 << col_black[j]) - 1  # black subsets

    # Subtract single cells that are double-counted
    single_cells = n * m

    answer = row_contrib + col_contrib - single_cells
    print(answer)

if __name__ == "__main__":
    solve()
"}

