    L = lcm(n, m)

    # Count how many days in one period have different colors
    different_days = []
    for i in range(L):
        day = i + 1
        color_a = a[(i - 1) % n]
        color_b = b[(i - 1) % m]
        if color_a != color_b:
            different_days.append(day)

    D = len(different_days)

