import sys

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def lcm(a, b):
    return a * b // gcd(a, b)

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    m = int(data[1])
    k = int(data[2])

    a = list(map(int, data[3:3+n]))
    b = list(map(int, data[3+n:3+n+m]))

    # Find all days in one cycle where colors differ
    cycle_length = lcm(n, m)
    diff_days = []

    for day in range(cycle_length):
        ch1 = a[day % n]
        ch2 = b[day % m]
        if ch1 != ch2:
            diff_days.append(day)

    c = len(diff_days)

    if k <= c:
        # Find the k-th different day directly
        ans = diff_days[k-1]
    else:
        # Find how many full cycles and the position in the next cycle
        full_cycles = (k - 1) // c
        remainder = (k - 1) % c
        ans = full_cycles * cycle_length + diff_days[remainder]

    print(ans + 1)  # Convert to 1-indexed

if __name__ == "__main__":
    solve()
"}

