def solve():
    s = input().strip()
    p = input().strip()

    n = len(s)
    m = len(p)

    # dp[i][j] = max number of non-overlapping p substrings in first i chars of s by removing j chars
    dp = [[-1] * (n + 1) for _ in range(n + 1)]
    dp[0][0] = 0

    for i in range(n):
        for j in range(n + 1):
            if dp[i][j] == -1:
                continue

            # Option 1: Remove the i-th character
            if j + 1 <= n:
                dp[i + 1][j + 1] = max(dp[i + 1][j + 1], dp[i][j])

            # Option 2: Keep the i-th character
            # Check if it matches the next character in p
            if j < m and s[i] == p[j]:
                if i + 1 <= n:
                    dp[i + 1][j] = max(dp[i + 1][j], dp[i][j] + (1 if j == m - 1 else 0))

    # Find the maximum number of non-overlapping p substrings for each x
    result = [-1] * (n + 1)
    for x in range(n + 1):
        max_count = 0
        for i in range(n + 1):
            if dp[i][x] != -1:
                max_count = max(max_count, dp[i][x])
        result[x] = max_count

    print(' '.join(map(str, result)))

solve()
