    # Find LIS length using standard O(n log n) algorithm
    lis = []
    for num in a:
        idx = bisect.bisect_left(lis, num)
        if idx == len(lis):
            lis.append(num)
        else:
            lis[idx] = num
    lis_length = len(lis)

    # Find left[i] = length of LIS ending at position i
    left = [1] * n
    for i in range(n):
        for j in range(i):
            if a[j] < a[i] and left[j] + 1 > left[i]:
                left[i] = left[j] + 1

    # Find right[i] = length of LIS starting at position i (or length of LIS ending at position i when considering reverse)
    right = [1] * n
    for i in range(n - 1, -1, -1):
        for j in range(i + 1, n):
            if a[i] < a[j] and right[j] + 1 > right[i]:
                right[i] = right[j] + 1

    result = []
    for i in range(n):
        # Can this element be part of some LIS?
        can_be_part = left[i] + right[i] - 1 == lis_length

        if not can_be_part:
            result.append('1')
        else:
            # Check if removing this element decreases the LIS length
            # Create a new array without this element and find LIS length
