            idx += 1

        if idx >= len(data):
            break

        n = int(data[idx])
        m = int(data[idx+1])
        idx += 2

        # Read edges
        edges = []
        for _ in range(m):
            a = int(data[idx])
            b = int(data[idx+1])
            edges.append((a, b))
            idx += 2

        # Build adjacency list
        adj = defaultdict(list)
        for a, b in edges:
            adj[a].append(b)

        # Find all vertices reachable from 1
        reachable = set()
        queue = deque([1])
        reachable.add(1)
        while queue:
            u = queue.popleft()
            for v in adj[u]:
                if v not in reachable:
                    reachable.add(v)
                    queue.append(v)

        # Find all vertices that can reach a cycle
        # First, find all vertices that are on a cycle
        visited = set()
        on_stack = set()
        in_cycle = set()

        def dfs(u):
            if u in on_stack:
                # Found a cycle
                for v in on_stack:
                    in_cycle.add(v)
                return True
            if u in visited:
                return False

            visited.add(u)
            on_stack.add(u)

            for v in adj[u]:
                if dfs(v):
                    # Cycle found
                    for w in on_stack:
                        in_cycle.add(w)
                    return True

            on_stack.remove(u)
            return False

        for u in reachable:
            if u not in visited:
                dfs(u)

        # Now, find all vertices that can reach a cycle
        can_reach_cycle = set()
        queue = deque([v for v in in_cycle])
        while queue:
            u = queue.popleft()
            can_reach_cycle.add(u)
            for v in adj[u]:
                if v not in can_reach_cycle:
                    can_reach_cycle.add(v)
                    queue.append(v)

        # Count paths using topological sort
        # First, find topological order of reachable vertices
        in_degree = defaultdict(int)
        for u in reachable:
            for v in adj[u]:
                in_degree[v] += 1

        top_order = []
        queue = deque([u for u in reachable if in_degree[u] == 0])
        while queue:
            u = queue.popleft()
            top_order.append(u)
            for v in adj[u]:
                in_degree[v] -= 1
                if in_degree[v] == 0:
                    queue.append(v)

        # Count paths
        dp = [0] * (n + 1)
        dp[1] = 1  # Empty path

        for u in top_order:
            if u == 1:
                continue  # Already counted
            for v in adj[u]:
                dp[v] += dp[u]

        # Prepare result
        result = []
        for v in range(1, n+1):
            if v not in reachable:
                result.append('0')
            elif v in can_reach_cycle:
                result.append('-1')
            else:
                if dp[v] == 1:
                    result.append('1')
                else:
                    result.append('2')

        results.append(' '.join(result))

    sys.stdout.write('\n'.join(results))
solve()
