    # we can get from the first i characters of s, having removed j characters,
    # and currently at position k in p (where k is the number of characters of p matched so far)
    dp = [[[ -1 for _ in range(m + 1)] for _ in range(n + 1)] for _ in range(n + 1)]

    # Base case: no characters processed, no characters removed, at position 0 in p
    dp[0][0][0] = 0

    for i in range(n):
        for j in range(n + 1):
            for k in range(m + 1):
                if dp[i][j][k] == -1:
                    continue

                # Option 1: remove the i-th character of s
                if j + 1 <= n:
                    dp[i + 1][j + 1][k] = max(dp[i + 1][j + 1][k], dp[i][j][k])

                # Option 2: keep the i-th character of s
                if k < m and s[i] == p[k]:
                    new_k = k + 1
                    if new_k == m:
                        # We've completed an occurrence of p
                        new_count = dp[i][j][k] + 1
                        new_k = 0
                        dp[i + 1][j][new_k] = max(dp[i + 1][j][new_k], new_count)
