def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    a = list(map(int, data[1:n+1]))
    b = list(map(int, data[n+1:2*n+1]))
    c = list(map(int, data[2*n+1:3*n+1]))

    # Strategy: feed hares with highest a[i] first, lowest a[i] last
    total_joy = 0

    # Feed hares with highest a[i] first (get a[i] joy)
    for i in range(n):
        if a[i] == max(a):
            total_joy += a[i]
            a[i] = -1  # mark as fed

    # Feed hares with lowest a[i] last (get c[i] joy)
    for i in range(n):
        if a[i] != -1:
            if c[i] == max(c):
                c[i] = -1
                total_joy += c[i]
        else:
            # last feeding order
            total_joy += c[i]

    # Feed remaining hares in between (get b[i] joy)
    # These are the hares that are neither fed first nor last
    remaining_b_feeding_order = []
    b_feeding_order = sorted([i for i in range(n) if a[i] != -1], key=lambda x: -b[x])

    for i in range(len(b_feeding_order)):
        if i < len(b_feeding_order) - 1:
            # Feed between first and last
            # So exactly one adjacent hare is full, one is hungry
            total_joy += b[b_feeding_order[i]]

