import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    x = int(data[1])
    arr = list(map(int, data[2:2+n]))

    freq = {}
    for num in arr:
        freq[num] = freq.get(num, 0) + 1

    ans = 0
    if x == 0:
        # Count pairs within the same number
        for a in freq:
            cnt = freq[a]
            ans += cnt * (cnt - 1) // 2
    else:
        # Count pairs (a, b) where a XOR b = x and a < b
        seen = set()
        for a in freq:
