                if a == b:
                    # a and b are the same, count pairs among its occurrences
                    cnt = freq[a]
                    ans += cnt * (cnt - 1) // 2
                else:
                    # Count pairs between different numbers
                    ans += freq[a] * freq[b]
                seen.add(a)
                seen.add(b)

    print(ans)

if __name__ == "__main__":
