    n = int(input())
    a = list(map(int, input().split()))

    # dp[i] = length of LIS ending at i
    # cnt[i] = number of ways to form LIS ending at i
    dp = [1] * n
    cnt = [1] * n

    for i in range(n):
        for j in range(i):
            if a[j] < a[i] and dp[j] + 1 > dp[i]:
                dp[i] = dp[j] + 1
                cnt[i] = cnt[j]
            elif a[j] < a[i] and dp[j] + 1 == dp[i]:
                cnt[i] += cnt[j]

    # dp_rev[i] = length of LIS starting at i (from the end)
    # cnt_rev[i] = number of ways to form LIS starting at i
    dp_rev = [1] * n
    cnt_rev = [1] * n

    for i in range(n - 1, -1, -1):
        for j in range(i + 1, n):
            if a[i] < a[j] and dp_rev[j] + 1 > dp_rev[i]:
                dp_rev[i] = dp_rev[j] + 1
                cnt_rev[i] = cnt_rev[j]
            elif a[i] < a[j] and dp_rev[j] + 1 == dp_rev[i]:
                cnt_rev[i] += cnt_rev[j]

    lis_length = max(dp)
    total_ways = cnt[dp.index(lis_length)]

    result = []
    for i in range(n):
        if dp[i] < lis_length or dp_rev[i] < lis_length:
            # Cannot be part of any LIS
            result.append('1')
        else:
            # Can be part of at least one LIS
