def solve(s, p):
    n = len(s)
    m = len(p)

    # dp[i][j] = maximum number of non-overlapping p substrings from first i chars of s,
    # with j chars of p matched so far
    dp = [[-1 for _ in range(n)] for _ in range(n + 1)]
    dp[0][0] = 0

    # Build transition table: where can we go from (i, j) by matching p[j] in s[i]?
    trans = [[[] for _ in range(n)] for _ in range(n + 1)]
    for i in range(n):
        for j in range(n):
            if j == n:
                continue
            if s[i] == p[j]:
                trans[i][j].append((i + 1, j + 1))

    # dp[i][j] update
    for i in range(n):
        for j in range(n):
            dp[i + 1][j] = max(dp[i + 1][j], dp[i][j] + (1 if (j + 1) % m == 0 else 0))

    for j in range(n):
        for t, nj in trans[j][t]:
            dp[nj][t] = max(dp[nj][t], dp[t][j])

    result = [0] * (n + 1)
    for x in range(n + 1):
        for i in range(n):
            for j in range(n):
                if dp[i + 1][j] != -1:
                    if (i - j) % m == 0:
                        # Complete pattern
                        result[x] = max(result[x], dp[i + 1][j] - ((i + 1 - j) % m != 0))
                    # End of string
                    pass

    print(' '.join(map(str, result)))

