        moves = []
        for dr in [-1, 1]:
            for dc in [-1, 1]:
                for d in range(1, N):
                    nr, nc = r + dr*d, c + dc*d
                    if 0 <= nr < N and 0 <= nc < N:
                        moves.append((nr, nc))
        return moves

    def rook_moves(r, c):
        moves = []
        for dr in [-1, 1]:
            for d in range(1, N):
                nr, nc = r + dr*d, c
                if 0 <= nr < N:
                    moves.append((nr, nc))
        for dc in [-1, 1]:
            for d in range(1, N):
                nr, nc = r, c + dc*d
                if 0 <= nc < N:
                    moves.append((nr, nc))
        return moves

    # Dijkstra's algorithm
    # State: (steps, replacements, row, col, piece, target)
    # piece: 0=knight, 1=bishop, 2=rook
    # target: number we need to reach next

    start_pos = positions[1]

