import sys

def solve():
    s = sys.stdin.readline().strip()
    p = sys.stdin.readline().strip()

    n = len(s)
    m = len(p)

    # dp[i][j]: maximum number of non-overlapping occurrences of p
    # using first i characters of s and matching first j characters of p
    dp = [[0] * (m + 1) for _ in range(n + 1)]

    for i in range(n):
        for j in range(m):
            # If we don't use s[i], we remove it
            dp[i+1][j] = max(dp[i+1][j], dp[i][j])

            # If we use s[i] to continue matching p
            if s[i] == p[j]:
                dp[i+1][j+1] = max(dp[i+1][j+1], dp[i][j])

                # If we've matched the entire p, we've found one occurrence
                if j + 1 == m:
                    dp[i+1][j+1] = max(dp[i+1][j+1], dp[i][j] + 1)

    # For each x from 0 to n, find the maximum value of dp[n][j] where n - j = x
    result = []
    for x in range(n + 1):
        max_val = 0
        for j in range(n - x + 1):
            if j <= m:
                max_val = max(max_val, dp[n][j])
        result.append(str(max_val))

    print(' '.join(result))

if __name__ == "__main__":
    solve()

