        s1 = strings[a - 1]
        s2 = strings[b - 1]
        new_string = s1 + s2

        # Check if the new string contains both '0' and '1'
        has_0 = '0' in new_string
        has_1 = '1' in new_string

        if has_0 and has_1:
            # Calculate maximum k such that 2^k <= len(new_string)
            k = int(math.log2(len(new_string))) + 1
            # Verify if all 2^k strings are actually present
            from itertools import product
            target_set = {"{0}{1}".format(b, a) for b, a in product([0, 1], repeat=k)}
            substring_set = {new_string[i:i+k] for i in range(len(new_string) - k + 1)}

            if substring_set == target_set:
                print(k)
            else:
                print(k - 1)
        else:
            print(0)

        strings.append(new_string)

solve()
