    def has_forbidden(s, l, r):
        # Convert to 0-indexed
        l -= 1
        r -= 1

        # Check if we have at least 3 characters
        if r - l + 1 < 3:
            return False

        # Check all possible 3-character substrings
        for i in range(l, r - 2):
            substr = s[i:i+3]
            if substr == 'zyx' or substr == 'xzy' or substr == 'yxz':
